function [fitresult, gof] = singleExpFitInt(y, x, plotFlag)
%CREATEFIT(X,Y)
%  Create a fit.
%
%  Data for 'singleExpFitInt' fit:
%      Y Output: y
%  Output:
%      fitresult : a fit object representing the fit.
%      gof : structure with goodness-of fit info.
%
%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 26-Jul-2017 13:15:14

if nargin < 3
    plotFlag = 0;
end
if nargin < 2
    x = [];
end


%% Fit: 'singleExpFitInt'.
[xData, yData] = prepareCurveData( x, y );

% Set up fittype and options.
ft = fittype( 'a*exp(-b*x)+c', 'independent', 'x', 'dependent', 'y' );
opts = fitoptions( 'Method', 'NonlinearLeastSquares' );
opts.Display = 'Off';
opts.StartPoint = [1 0.1 0];

% Fit model to data.
[fitresult, gof] = fit( xData, yData, ft, opts );

if plotFlag == 1
    % Plot fit with data.
    figure( 'Name', 'singleExpFitInt' );
    h = plot( fitresult, xData, yData );
    % Label axes
    xlabel x
    ylabel y
    grid on
end

